class Solution {
public:
    vector<int> distributeCandies(int candies, int num_people) {
        vector<int> res(num_people, 0);
        int give = 1;
        int idx = 0;
        while (candies > 0) {
            int amount = min(candies, give);
            res[idx % num_people] += amount;
            candies -= amount;
            give++;
            idx++;
        }
        return res;
    }
};

class Solution {
    public int[] distributeCandies(int candies, int num_people) {
        int[] res = new int[num_people];
        int give = 1;
        int idx = 0;
        while (candies > 0) {
            int amount = Math.min(candies, give);
            res[idx % num_people] += amount;
            candies -= amount;
            give++;
            idx++;
        }
        return res;
    }
}

var distributeCandies = function(candies, num_people) {
    const res = new Array(num_people).fill(0);
    let give = 1;
    let idx = 0;
    while (candies > 0) {
        const amount = Math.min(candies, give);
        res[idx % num_people] += amount;
        candies -= amount;
        give++;
